window.getCheongryeomType = function(scoreMap){
  const order = CHEONGRYEOM_CONTENT.virtues.map((v, index) => ({
    key: v.key,
    name: v.name,
    score: Number(scoreMap?.[v.key] || 0),
    order: index
  }));

  const ranked = order
    .slice()
    .sort((a,b) => (b.score - a.score) || (a.order - b.order));

  // 응답 근거가 거의 없을 때는 억지로 역사 인물을 매칭하지 않는다.
  if ((ranked[0]?.score || 0) === 0 && (ranked[1]?.score || 0) === 0) {
    return {
      name:'청렴 탐색형',
      figure:'유형 판정 보류',
      symbol:'🌱',
      summary:'아직 청렴역량 유형을 판단할 수 있는 응답이 충분하지 않습니다.',
      mission:'다음 활동에서는 시간 안에 문항을 제출하고 나의 판단 기준을 확인해보기',
      primary: ranked[0] || {key:'honesty',name:'정직',score:0},
      secondary: ranked[1] || {key:'promise',name:'약속',score:0},
      pairKey:''
    };
  }

  const top = ranked.slice(0,2);
  const idx = Object.fromEntries(
    CHEONGRYEOM_CONTENT.virtues.map((v,i)=>[v.key,i])
  );
  const keys = top.map(x=>x.key).sort((a,b)=>idx[a]-idx[b]);
  const found = CHEONGRYEOM_TYPES.find(t =>
    t.virtues[0] === keys[0] && t.virtues[1] === keys[1]
  );

  return {
    ...(found || {
      name:'청렴 성장형', figure:'역사 인물 매칭 준비 중', symbol:'🌳',
      summary:'여러 청렴가치가 고르게 나타나는 성장형입니다.',
      mission:'가장 낮은 청렴역량 한 가지를 골라 오늘 실천해보기'
    }),
    primary: top[0],
    secondary: top[1],
    pairKey: keys.join('|')
  };
};



/* v8.1 무이동 디지털 직무회의 평가 로직 */
window.CHEONGRYEOM_EVALUATE_TEAM_ROLE = function(team, answer){
  const clamp=x=>Math.max(0,Math.min(100,Math.round(x)));
  if(!team||!answer) return {score:0,impact:{},details:[]};
  const w=answer.work||{}, roleKey=String(w.roleKey||''), role=team.roles?.[roleKey];
  if(!role) return {score:0,impact:{},details:[]};
  const core=Number(answer.choice)===Number(role.correct||0)?30:(Number.isInteger(Number(answer.choice))?10:0);
  const risk=w.riskLevel?10:0;
  const preliminary=w.preliminaryVendor?10:0;
  const note=String(w.note||'').trim(); let noteScore=note.length>=30?18:note.length>=15?12:note.length>=8?6:0;
  (role.keywords||[]).slice(0,4).forEach(k=>{if(note.includes(k))noteScore+=3;}); noteScore=Math.min(30,noteScore);
  const question=String(w.question||'').trim(); let questionScore=question.length>=18?20:question.length>=8?14:question.length?5:0;
  const score=clamp(core+risk+preliminary+noteScore+questionScore);
  const impact={honesty:score,responsibility:score,fairness:Math.round(score*.9),care:Math.round(score*.75),promise:Math.round(score*.75),restraint:Math.round(score*.75)};
  return {score,impact,details:[['핵심정보 해석',core,30],['위험도 판단',risk,10],['1차 대안 판단',preliminary,10],['직무근거 분석',noteScore,30],['교차확인 질문',questionScore,20]]};
};
