  const conflict=Number(w.conflictResponse)===0?15:0,twist=Number(w.twistResponse)===0?15:0,vendor=String(w.vendor||'')===String(team.finalVendor)?15:0;
  const reason=String(w.reason||'').trim();let reasonScore=reason.length>=35?7:reason.length>=20?4:0;(team.reasonKeywords||[]).slice(0,5).forEach(k=>{if(reason.includes(k))reasonScore+=1;});if(w.influenceUid)reasonScore+=3;reasonScore=Math.min(15,reasonScore);
